/**
 * Write a function to split a string at lowercase letters.
 * > splitLowerstring(string("AbCd"))
 * {string("bC"), string("d")}
 * > splitLowerstring(string("Python"))
 * {string("y"), string("t"), string("h"), string("o"), string("n")}
 * > splitLowerstring(string("Programming"))
 * {string("r"), string("o"), string("g"), string("r"), string("a"), string("m"), string("m"), string("i"), string("n"), string("g")}
 */
vector<string> splitLowerstring(string text) {
    vector<string> result;
    string temp;
    for (int i = 0; i < text.size(); i++) {
        if (islower(text[i])) {
            if (temp.size() > 0) {
                result.push_back(temp);
                temp = "";
            }
            result.push_back(string(1, text[i]));
        } else {
            temp += text[i];
        }
    }
    if (temp.size() > 0) {
        result.push_back(temp);
    }
    return result;
}


int main() {
    string text = "AbCd";
    vector<string> result = splitLowerstring(text);
    for (int i = 0; i < result.size(); i++) {
        cout << result[i] << endl;
    }
    return 0;
}


