/**
 * Write a c++ function to find the product of non-repeated elements in a given array.
 * > findProduct(vector<int>{1, 1, 2, 3}, 4)
 * 6
 * > findProduct(vector<int>{1, 2, 3, 1, 1}, 5)
 * 6
 * > findProduct(vector<int>{1, 1, 4, 5, 6}, 5)
 * 120
 */
int findProduct(vector<int> arr, int n) {
    int product = 1;
    int product_of_non_repeated = 1;
    int product_of_repeated = 1;
    for (int i = 0; i < n; i++) {
        product *= arr[i];
        if (arr[i] != arr[i - 1]) {
            product_of_non_repeated *= arr[i];
        } else {
            product_of_repeated *= arr[i];
        }
    }
    return product / (product_of_non_repeated * product_of_repeated);
}


