 * > binomialCoeff(5, 2)
 * 10
 * > binomialCoeff(4, 3)
 * 4
 * > binomialCoeff(3, 2)
 * 3
 */
int binomialCoeff(int n, int k) {
    if (k > n) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    if (k == 1 || k == n - 1) {
        return n;
    }
    return binomialCoeff(n - 1, k - 1) + binomialCoeff(n - 1, k);
}


