 * > isOctagonal(5)
 * 65
 * > isOctagonal(10)
 * 280
 * > isOctagonal(15)
 * 645
 */
int isOctagonal(int n) {
    int i = 1;
    int j = 1;
    int k = 1;
    int sum = 1;
    while (sum < n) {
        sum = i + j + k;
        i += 2;
        j += 2;
        k += 2;
    }
    return sum;
}


