/**
 * Write a function to find the maximum length of the subsequence with difference between adjacent elements for the given array.
 * > maxLenSub(vector<int>{2, 5, 6, 3, 7, 6, 5, 8}, 8)
 * 5
 * > maxLenSub(vector<int>{-2, -1, 5, -1, 4, 0, 3}, 7)
 * 4
 * > maxLenSub(vector<int>{9, 11, 13, 15, 18}, 5)
 * 1
 */
int maxLenSub(vector<int> arr, int n) {
    int maxLen = 0;
    int len = 0;
    int diff = 0;
    for (int i = 0; i < arr.size(); i++) {
        if (arr[i] - diff == n) {
            len++;
            diff = arr[i];
            maxLen = max(maxLen, len);
        } else {
            len = 0;
            diff = arr[i];
        }
    }
    return maxLen;
}


