/**
 * Write a c++ function to count number of substrings with the sum of digits equal to their length.
 * > countSubstrings(string("112112"), 6)
 * 6
 * > countSubstrings(string("111"), 3)
 * 6
 * > countSubstrings(string("1101112"), 7)
 * 12
 */
int countSubstrings(string s, int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = i; j < n; j++) {
            sum += s[j] - '0';
            if (sum == j - i + 1) {
                count++;
            }
        }
    }
    return count;
}


int main() {
    cout << countSubstrings("112112", 6) << endl;
    cout << countSubstrings("111", 3) << endl;
    cout << countSubstrings("1101112", 7) << endl;
    return 0;
}


