 * 23
 */
int maxDifference(vector<vector<int>> testList) {
    int maxDiff = 0;
    for (int i = 0; i < testList.size(); i++) {
        for (int j = i + 1; j < testList.size(); j++) {
            int diff = testList[j][0] - testList[i][1];
            if (diff > maxDiff) {
                maxDiff = diff;
            }
        }
    }
    return maxDiff;
}


