 * Write a function to split the given string with multiple delimiters by using regex.
 * > multipleSplit(string("Forces of the \ndarkness*are coming into the play."))
 * {string("Forces of the "), string("darkness"), string("are coming into the play.")}
 * > multipleSplit(string("Mi Box runs on the \n Latest android*which has google assistance and chromecast."))
 * {string("Mi Box runs on the "), string(" Latest android"), string("which has google assistance and chromecast.")}
 * > multipleSplit(string("Certain services\nare subjected to change*over the seperate subscriptions."))
 * {string("Certain services"), string("are subjected to change"), string("over the seperate subscriptions.")}
 */
vector<string> multipleSplit(string text) {
    vector<string> result;
    regex reg("\\s|\\*");
    sregex_token_iterator iter(text.begin(), text.end(), reg, -1);
    sregex_token_iterator end;
    while (iter != end) {
        result.push_back(*iter++);
    }
    return result;
}


int main() {
    string text = "Forces of the \ndarkness*are coming into the play.";
    vector<string> result = multipleSplit(text);
    for (string s : result) {
        cout << s << endl;
    }

    text = "Mi Box runs on the \n Latest android*which has google assistance and chromecast.";
    result = multipleSplit(text);
    for (string s : result) {
        cout << s << endl;
    }

    text = "Certain services\nare subjected to change*over the seperate subscriptions.";
    result = multipleSplit(text);
    for (string s : result) {
        cout << s << endl;
    }

    return 0;
}


