/**
 * Write a c++ function to count the number of squares in a rectangle.
 * > countSquares(4, 3)
 * 20
 * > countSquares(2, 2)
 * 5
 * > countSquares(1, 1)
 * 1
 */
int countSquares(int m, int n) {
    int count = 0;
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (i == j) {
                count += i;
            }
        }
    }
    return count;
}


