 * > isDiff(1212112)
 * true
 * > isDiff(1212)
 * false
 */
bool isDiff(int n) {
    int sum_even = 0, sum_odd = 0;
    while (n > 0) {
        int digit = n % 10;
        if (digit % 2 == 0) {
            sum_even += digit;
        } else {
            sum_odd += digit;
        }
        n /= 10;
    }
    return sum_even != sum_odd;
}


