/**
 * Write a c++ function to find number of integers with odd number of set bits.
 * > countWithOddSetbits(5)
 * 3
 * > countWithOddSetbits(10)
 * 5
 * > countWithOddSetbits(15)
 * 8
 */
int countWithOddSetbits(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        int setBits = 0;
        int num = i;
        while (num > 0) {
            if (num & 1) {
                setBits++;
            }
            num = num >> 1;
        }
        if (setBits & 1) {
            count++;
        }
    }
    return count;
}


