 * 2
 */
int sequence(int n) {
    if (n == 1) return 1;
    if (n == 2) return 1;
    if (n == 3) return 2;

    int prev = 1, curr = 1, next = 2;
    for (int i = 4; i <= n; i++) {
        next = prev + curr;
        prev = curr;
        curr = next;
    }

    return next;
}


