 * > isUndulating(string("1212121"))
 * true
 * > isUndulating(string("1991"))
 * false
 * > isUndulating(string("121"))
 * true
 */
bool isUndulating(string n) {
    int i = 0;
    int j = n.size() - 1;
    while (i < j) {
        if (n[i] == n[j]) {
            i++;
            j--;
        } else if (n[i] > n[j]) {
            i++;
        } else {
            j--;
        }
    }
    return i == j;
}


