 */
int nextSmallestPalindrome(int num) {
    string s = to_string(num);
    int n = s.size();
    int i = 0;
    while (i < n/2) {
        if (s[i] != s[n-i-1]) {
            break;
        }
        i++;
    }
    if (i == n/2) {
        return num;
    }
    int j = n-i-1;
    if (s[i] > s[j]) {
        s[j] = s[i];
    } else {
        s[i] = s[j];
    }
    s[i+1] = s[j-1];
    s[j] = s[i];
    s[j-1] = s[i+1];
    s[i] = s[j];
    s[j] = s[i];
    return stoi(s);
}


