 * 3
 * > kthElement(vector<int>{17, 24, 8, 23}, 4, 3)
 * 8
 * > kthElement(vector<int>{16, 21, 25, 36, 4}, 5, 4)
 * 36
 */
int kthElement(vector<int> arr, int n, int k) {
    int l = 0, r = n - 1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (arr[m] == k) return arr[m];
        if (arr[m] < k) l = m + 1;
        else r = m - 1;
    }
    return -1;
}


