 * > commonInNestedLists(vector<vector<int>>{{2, 3, 4, 1}, {4, 5}, {6, 4, 8}, {4, 5}, {6, 8, 4}})
 * {4}
 */
vector<int> commonInNestedLists(vector<vector<int>> nestedlist) {
    vector<int> res;
    unordered_map<int, int> m;
    for (auto &list : nestedlist) {
        for (auto &item : list) {
            m[item]++;
        }
    }
    for (auto &item : m) {
        if (item.second == nestedlist.size()) {
            res.push_back(item.first);
        }
    }
    return res;
}

