 * 1
 */
int search(vector<int> arr, int n) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (mid == 0 || mid == n - 1) {
            return arr[mid];
        }
        if (arr[mid] == arr[mid - 1] && arr[mid] == arr[mid + 1]) {
            low = mid + 1;
        } else if (arr[mid] == arr[mid - 1]) {
            high = mid - 1;
        } else if (arr[mid] == arr[mid + 1]) {
            low = mid + 1;
        } else {
            return arr[mid];
        }
    }
    return -1;
}


