/**
 * Write a function to sum all amicable numbers from 1 to a specified number.
 * > amicableNumbersSum(999)
 * 504
 * > amicableNumbersSum(9999)
 * 31626
 * > amicableNumbersSum(99)
 * 0
 */
int amicableNumbersSum(int limit) {
    int sum = 0;
    for (int i = 1; i <= limit; i++) {
        int a = i;
        int b = i;
        while (a != 1) {
            b += a % 10;
            a /= 10;
        }
        a = i;
        while (b != 1) {
            a += b % 10;
            b /= 10;
        }
        if (a == i && a != b && a != i) {
            sum += a;
        }
    }
    return sum;
}


