 */
double calElectbill(int units) {
    double bill = 0;
    if (units <= 100) {
        bill = units * 0.5;
    } else if (units <= 200) {
        bill = 100 * 0.5 + (units - 100) * 0.7;
    } else if (units <= 300) {
        bill = 100 * 0.5 + 100 * 0.7 + (units - 200) * 0.9;
    } else {
        bill = 100 * 0.5 + 100 * 0.7 + 100 * 0.9 + (units - 300) * 1.1;
    }
    return bill;
}


