 * 7
 */
int longestSubseqWithDiffOne(vector<int> arr, int n) {
    int max_len = 0;
    int len = 0;
    int prev = -1;

    for (int i = 0; i < n; i++) {
        if (arr[i] - prev == 1) {
            len++;
        } else {
            max_len = max(max_len, len);
            len = 1;
        }
        prev = arr[i];
    }

    return max(max_len, len);
}


