 * false
 * > doesContainB(3, 2, 5)
 * false
 */
bool doesContainB(int a, int b, int c) {
    int n = 0;
    while (true) {
        if (n == c) return true;
        if (n < 0) return false;
        n = a * n + b;
    }
}


