    int mid = x.size() / 2;
    vector<int> left = mergeSort(vector<int>(x.begin(), x.begin() + mid));
    vector<int> right = mergeSort(vector<int>(x.begin() + mid, x.end()));

    vector<int> result;
    int i = 0, j = 0;
