 * > isValidParenthese(string("(){}[]"))
 * true
 * > isValidParenthese(string("()[{)}"))
 * false
 * > isValidParenthese(string("()"))
 * true
 */
bool isValidParenthese(string str1) {
    stack<char> st;
    for (int i = 0; i < str1.length(); i++) {
        if (str1[i] == '(' || str1[i] == '{' || str1[i] == '[') {
            st.push(str1[i]);
        } else {
            if (st.empty()) {
                return false;
            }
            char top = st.top();
            st.pop();
            if (str1[i] == ')' && top != '(') {
                return false;
            }
            if (str1[i] == '}' && top != '{') {
                return false;
            }
            if (str1[i] == ']' && top != '[') {
                return false;
            }
        }
    }
    return st.empty();
}


