/**
 * Write a function to count all the distinct pairs having a difference of k in any array.
 * > countPairs(vector<int>{1, 5, 3, 4, 2}, 5, 3)
 * 2
 * > countPairs(vector<int>{8, 12, 16, 4, 0, 20}, 6, 4)
 * 5
 * > countPairs(vector<int>{2, 4, 1, 3, 4}, 5, 2)
 * 3
 */
int countPairs(vector<int> arr, int n, int k) {
    int count = 0;
    unordered_map<int, int> m;
    for (int i = 0; i < n; i++) {
        if (m.find(arr[i] - k) != m.end()) {
            count += m[arr[i] - k];
        }
        if (m.find(arr[i] + k) != m.end()) {
            count += m[arr[i] + k];
        }
        m[arr[i]]++;
    }
    return count;
}


int main() {
    cout << countPairs(vector<int>{1, 5, 3, 4, 2}, 5, 3) << endl;
    cout << countPairs(vector<int>{8, 12, 16, 4, 0, 20}, 6, 4) << endl;
    cout << countPairs(vector<int>{2, 4, 1, 3, 4}, 5, 2) << endl;
    return 0;
}


