    int sqrt = sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            int sqrt2 = sqrt(n / i);
            for (int j = 1; j <= sqrt2; j++) {
                if (n / i % j == 0) {
                    return true;
                }
            }
        }
    }
    return false;
}


