 * > hammingDistance(4, 8)
 * 2
 * > hammingDistance(2, 4)
 * 2
 * > hammingDistance(1, 2)
 * 2
 */
int hammingDistance(int n1, int n2) {
    int count = 0;
    int n = n1 ^ n2;
    while (n) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}


