 * > minOperations(2, 4)
 * 1
 * > minOperations(4, 10)
 * 4
 * > minOperations(1, 4)
 * 3
 */
int minOperations(int a, int b) {
    int x = a, y = b;
    int count = 0;
    while (x != y) {
        if (x > y) {
            x -= y;
            count++;
        } else {
            y -= x;
            count++;
        }
    }
    return count;
}


