 */
vector<int> extractMinMax(vector<int> testTup, int k) {
    vector<int> res;
    int n = testTup.size();
    if(n < k)
        return res;

    priority_queue<int, vector<int>, greater<int>> minHeap;
    priority_queue<int> maxHeap;

    for(int i=0; i<k; i++) {
        minHeap.push(testTup[i]);
        maxHeap.push(testTup[i]);
    }

    for(int i=k; i<n; i++) {
        if(testTup[i] > maxHeap.top()) {
            maxHeap.pop();
            maxHeap.push(testTup[i]);
        }

        if(testTup[i] < minHeap.top()) {
            minHeap.pop();
            minHeap.push(testTup[i]);
        }
    }

    while(!minHeap.empty()) {
        res.push_back(minHeap.top());
        minHeap.pop();
    }

    while(!maxHeap.empty()) {
        res.push_back(maxHeap.top());
        maxHeap.pop();
    }

    return res;

