 * Write a function to re-arrange the elements of the given array so that all negative elements appear before positive ones.
 * > reArrangeArray(vector<int>{-1, 2, -3, 4, 5, 6, -7, 8, 9}, 9)
 * {-1, -3, -7, 4, 5, 6, 2, 8, 9}
 * > reArrangeArray(vector<int>{12, -14, -26, 13, 15}, 5)
 * {-14, -26, 12, 13, 15}
 * > reArrangeArray(vector<int>{10, 24, 36, -42, -39, -78, 85}, 7)
 * {-42, -39, -78, 10, 24, 36, 85}
 */
vector<int> reArrangeArray(vector<int> arr, int n) {
    int i = 0;
    int j = n - 1;

    while (i < j) {
        while (arr[i] < 0 && i < j) {
            i++;
        }

        while (arr[j] >= 0 && i < j) {
            j--;
        }

        if (i < j) {
            swap(arr[i], arr[j]);
        }
    }

    return arr;
}


