 * 84
 */
int getTotalNumberOfSequences(int m, int n) {
    if (n == 1) return 1;
    if (n == 2) return m;
    if (n == 3) return m * (m - 1) / 2;

    int dp[n + 1];
    dp[1] = 1;
    dp[2] = m;
    dp[3] = m * (m - 1) / 2;

    for (int i = 4; i <= n; i++) {
        dp[i] = 0;
        for (int j = 1; j <= m; j++) {
            dp[i] += dp[i - 1];
        }
    }

    return dp[n];
}


