 * > babylonianSquareroot(10)
 * 3.162277660168379
 * > babylonianSquareroot(2)
 * 1.414213562373095
 * > babylonianSquareroot(9)
 * 3.0
 */
double babylonianSquareroot(int number) {
    double x = number;
    double y = 1;
    while (abs(x - y) > 0.000000000000001) {
        x = (x + y) / 2;
        y = number / x;
    }
    return x;
}


