    int n = str.size();
    int dp[n][n];
    for(int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }

    for(int i = 0; i < n - 1; i++) {
        if(str[i] == str[i + 1]) {
            dp[i][i + 1] = 2;
        } else {
            dp[i][i + 1] = 1;
        }
    }

    for(int i = 2; i < n; i++) {
        for(int j = 0; j < n - i; j++) {
            int k = j + i;
            if(str[j] == str[k]) {
                dp[j][k] = 2 + dp[j + 1][k - 1];
            } else {
                dp[j][k] = max(dp[j + 1][k], dp[j][k - 1]);
            }
        }
    }

    return dp[0][n - 1];
}


