    string word;
    for (int i = 0; i < text.size(); i++) {
        if (text[i] == ' ' || i == text.size() - 1) {
            if (word.size() > 0 && (word[0] == 'a' || word[0] == 'e')) {
                words.push_back(word);
            }
            word = "";
        } else {
            word += text[i];
        }
    }
    return words;
}


