 * 2
 * > countPrimesNums(10)
 * 4
 * > countPrimesNums(100)
 * 25
 */
int countPrimesNums(int n) {
    int count = 0;
    for (int i = 2; i < n; i++) {
        bool isPrime = true;
        for (int j = 2; j < i; j++) {
            if (i % j == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            count++;
        }
    }
    return count;
}


