/**
 * Write a c++ function to find sum of even index binomial coefficients.
 * > evenBinomialCoeffSum(4)
 * 8
 * > evenBinomialCoeffSum(6)
 * 32
 * > evenBinomialCoeffSum(2)
 * 2
 */
int evenBinomialCoeffSum(int n) {
    int sum = 0;
    for (int i = 0; i <= n; i += 2) {
        sum += binomialCoeff(n, i);
    }
    return sum;
}

int binomialCoeff(int n, int k) {
    if (k > n) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    return binomialCoeff(n - 1, k - 1) + binomialCoeff(n - 1, k);
}

