 * > countNoOfWays(3, 2)
 * 6
 * > countNoOfWays(4, 4)
 * 228
 */
int countNoOfWays(int n, int k) {
    if (n == 0 || k == 0) return 0;
    if (n == 1) return k;
    if (n == 2) return k * k;

    int dp[n + 1][k];
    memset(dp, 0, sizeof(dp));

    dp[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < k; j++) {
            dp[i][j] = dp[i - 1][j];
            if (j > 0) dp[i][j] += dp[i - 1][j - 1];
            if (j < k - 1) dp[i][j] += dp[i - 1][j + 1];
        }
    }

    int ans = 0;
    for (int i = 0; i < k; i++) {
        ans += dp[n][i];
    }

    return ans;
}


