 */
vector<string> permuteString(string str) {
    vector<string> result;
    if (str.size() == 0) {
        result.push_back("");
        return result;
    }

    for (int i = 0; i < str.size(); i++) {
        string newStr = str;
        newStr.erase(i, 1);
        vector<string> subResult = permuteString(newStr);
        for (int j = 0; j < subResult.size(); j++) {
            result.push_back(str[i] + subResult[j]);
        }
    }

    return result;
}


