/**
 * Write a function to find the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).
 * > getMaxSum(60)
 * 106
 * > getMaxSum(10)
 * 12
 * > getMaxSum(2)
 * 2
 */
int getMaxSum(int n) {
    if (n <= 5) return n;
    int max = 0;
    for (int i = 1; i <= n; i++) {
        int sum = getMaxSum(n / i);
        if (sum > max) max = sum;
    }
    return max + n;
}


