 * > sumOfDigits(vector<int>{10, 2, 56})
 * 14
 * > sumOfDigits(vector<int>{10, 20, -4, 5, -70})
 * 19
 */
int sumOfDigits(vector<int> nums) {
    int sum = 0;
    for (int num : nums) {
        int temp = num;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
    }
    return sum;
}


