 * > overlapping(vector<int>{1, 2, 3, 4, 5}, vector<int>{6, 7, 8, 9})
 * false
 * > overlapping(vector<int>{1, 2, 3}, vector<int>{4, 5, 6})
 * false
 * > overlapping(vector<int>{1, 4, 5}, vector<int>{1, 4, 5})
 * true
 */
bool overlapping(vector<int> list1, vector<int> list2) {
    int i = 0, j = 0;
    while (i < list1.size() && j < list2.size()) {
        if (list1[i] == list2[j]) {
            return true;
        } else if (list1[i] < list2[j]) {
            i++;
        } else {
            j++;
        }
    }
    return false;
}


