/**
 * Write a function to find the maximum sum we can make by dividing number in three parts recursively and summing them up together for the given number.
 * > breaksum(12)
 * 13
 * > breaksum(24)
 * 27
 * > breaksum(23)
 * 23
 */
int breaksum(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    if (n == 2) return 2;
    if (n == 3) return 3;

    int max = 0;
    for (int i = 1; i <= n / 3; i++) {
        int left = breaksum(i);
        int right = breaksum(n - i);
        int mid = breaksum(n - left - right);
        max = max(max, left + right + mid);
    }
    return max;
}


