 * > getMaxgold(vector<vector<int>>{{10, 20}, {30, 40}}, 2, 2)
 * 70
 * > getMaxgold(vector<vector<int>>{{4, 9}, {3, 7}}, 2, 2)
 * 13
 */
int getMaxgold(vector<vector<int>> gold, int m, int n) {
    int dp[m][n];
    memset(dp, 0, sizeof(dp));
    dp[0][0] = gold[0][0];
    for (int i = 1; i < m; i++) {
        dp[i][0] = dp[i - 1][0] + gold[i][0];
    }
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + gold[0][j];
    }
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + gold[i][j];
        }
    }
    return dp[m - 1][n - 1];
}


