/**
 * Write a function to determine if there is a subset of the given set with sum equal to the given sum.
 * > isSubsetSum(vector<int>{3, 34, 4, 12, 5, 2}, 6, 9)
 * true
 * > isSubsetSum(vector<int>{3, 34, 4, 12, 5, 2}, 6, 30)
 * false
 * > isSubsetSum(vector<int>{3, 34, 4, 12, 5, 2}, 6, 15)
 * true
 */
bool isSubsetSum(vector<int> set, int n, int sum) {
    // if sum is 0 then answer is true
    if (sum == 0) return true;
    // if sum is not 0 and set is empty then answer is false
    if (n == 0) return false;
    // if last element is greater than sum then we ignore it
    if (set[n - 1] > sum) return isSubsetSum(set, n - 1, sum);
    // if last element is equal to sum then we return true
    if (set[n - 1] == sum) return true;
    // if last element is smaller than sum then we check for remaining elements
    return isSubsetSum(set, n - 1, sum) || isSubsetSum(set, n - 1, sum - set[n - 1]);
}


