 * 5
 * > firstFactorialDivisibleNumber(15)
 * 5
 * > firstFactorialDivisibleNumber(5)
 * 4
 */
int firstFactorialDivisibleNumber(int x) {
    int i = 1;
    while (true) {
        int fact = 1;
        for (int j = 1; j <= i; j++) {
            fact *= j;
        }
        if (fact % x == 0) {
            return i;
        }
        i++;
    }
}


