 */
int frequencyOfLargest(int n, vector<int> arr) {
    int largest = arr[0];
    int largest_count = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
            largest_count = 1;
        } else if (arr[i] == largest) {
            largest_count++;
        }
    }
    return largest_count;
}


