/**
 * Write a function to find the sum of maximum increasing subsequence of the given array.
 * > maxSumIncreasingSubsequence(vector<int>{1, 101, 2, 3, 100, 4, 5}, 7)
 * 106
 * > maxSumIncreasingSubsequence(vector<int>{3, 4, 5, 10}, 4)
 * 22
 * > maxSumIncreasingSubsequence(vector<int>{10, 5, 4, 3}, 4)
 * 10
 */
int maxSumIncreasingSubsequence(vector<int> arr, int n) {
    vector<int> dp(n, 0);
    int maxSum = 0;
    for (int i = 0; i < n; i++) {
        dp[i] = arr[i];
        for (int j = 0; j < i; j++) {
            if (arr[j] < arr[i]) {
                dp[i] = max(dp[i], dp[j] + arr[i]);
            }
        }
        maxSum = max(maxSum, dp[i]);
    }
    return maxSum;
}


int main() {
    cout << maxSumIncreasingSubsequence(vector<int>{1, 101, 2, 3, 100, 4, 5}, 7) << endl;
    cout << maxSumIncreasingSubsequence(vector<int>{3, 4, 5, 10}, 4) << endl;
    cout << maxSumIncreasingSubsequence(vector<int>{10, 5, 4, 3}, 4) << endl;
    return 0;
}


