 * string("PythoN")
 * > capitalizeFirstLastLetters(string("bigdata"))
 * string("BigdatA")
 * > capitalizeFirstLastLetters(string("Hadoop"))
 * string("HadooP")
 */
string capitalizeFirstLastLetters(string str1) {
    string str2 = "";
    int len = str1.length();
    for (int i = 0; i < len; i++) {
        if (i == 0 || i == len - 1) {
            str2 += toupper(str1[i]);
        } else {
            str2 += str1[i];
        }
    }
    return str2;
}


