 * 2
 */
int minCoins(vector<int> coins, int m, int v) {
    int n = coins.size();
    vector<vector<int>> dp(n + 1, vector<int>(v + 1, 0));

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= v; j++) {
            if (coins[i - 1] <= j) {
                dp[i][j] = min(dp[i - 1][j], 1 + dp[i][j - coins[i - 1]]);
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    return dp[n][v];
}


