 * {19, 27}
 */
vector<int> searchLiteral(string pattern, string text) {
    vector<int> result;
    int n = pattern.size();
    int m = text.size();

    int i = 0;
    int j = 0;

    while (i < m && j < n) {
        if (text[i] == pattern[j]) {
            j++;
            i++;
        } else {
            i = i - j + 1;
            j = 0;
        }
    }

    if (j == n) {
        result.push_back(i - n);
        result.push_back(i - 1);
    }

    return result;
}


