 * {14, 17}
 */
vector<int> nthItems(vector<int> list, int n) {
    vector<int> result;
    int i = 0;
    for (int item : list) {
        if (i % n == 0) {
            result.push_back(item);
        }
        i++;
    }
    return result;
}


