/**
 * Write a c++ function to find the first repeated word in a given string.
 * > firstRepeatedWord(string("ab ca bc ab"))
 * string("ab")
 * > firstRepeatedWord(string("ab ca bc"))
 * string("None")
 * > firstRepeatedWord(string("ab ca bc ca ab bc"))
 * string("ca")
 */
string firstRepeatedWord(string str1) {
    stringstream ss(str1);
    string word;
    unordered_set<string> words;
    while (ss >> word) {
        if (words.find(word) != words.end()) {
            return word;
        }
        words.insert(word);
    }
    return "None";
}


