/**
 * Write a c++ function to find the sum of hamming distances of all consecutive numbers from o to n.
 * > totalHammingDistance(4)
 * 7
 * > totalHammingDistance(2)
 * 3
 * > totalHammingDistance(5)
 * 8
 */
int totalHammingDistance(int n) {
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        int x = i;
        int count = 0;
        while (x) {
            count += x & 1;
            x >>= 1;
        }
        sum += count * (n - i + 1);
    }
    return sum;
}


