/**
 * Write a function to get the sum of a non-negative integer.
 * > sumDigits(345)
 * 12
 * > sumDigits(12)
 * 3
 * > sumDigits(97)
 * 16
 */
int sumDigits(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}


